package dev.mmm.discordia.core;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The bundled crafting table, extracted from the NotEnoughUpdates repo.
 *
 * <p>2,002 outputs, each a 3x3 grid flattened to the ingredients that are actually present. The
 * source file is generated by {@code tools/build-craft-data.mjs} and committed, so a scan never
 * needs a third-party service to know what an item is made of.
 *
 * <p>Ingredient ids are the same internal names the Hypixel auction and bazaar APIs use, which is
 * what lets one cost resolver read all three price sources.
 */
public final class CraftRecipes {

    public record Ingredient(String id, int count) {
    }

    private static volatile Map<String, List<Ingredient>> recipes;
    private static volatile int size;

    private CraftRecipes() {
    }

    /** Every craftable output. Loading is lazy and happens once per process. */
    public static Map<String, List<Ingredient>> all() {
        load();
        return recipes;
    }

    /** The ingredients for one output, or {@code null} when it is not craftable. */
    public static List<Ingredient> of(String id) {
        load();
        return recipes.get(id);
    }

    public static boolean craftable(String id) {
        load();
        return recipes.containsKey(id);
    }

    public static int size() {
        load();
        return size;
    }

    private static void load() {
        if (recipes != null) {
            return;
        }
        synchronized (CraftRecipes.class) {
            if (recipes != null) {
                return;
            }
            Map<String, List<Ingredient>> parsed = new HashMap<>();
            try (InputStream in = CraftRecipes.class.getResourceAsStream("/recipes.json")) {
                if (in == null) {
                    throw new IllegalStateException("recipes.json is missing from the jar");
                }
                JsonObject root = JsonParser.parseReader(
                        new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
                JsonObject table = root.getAsJsonObject("recipes");
                for (Map.Entry<String, JsonElement> entry : table.entrySet()) {
                    List<Ingredient> ingredients = new ArrayList<>();
                    for (JsonElement slot : entry.getValue().getAsJsonArray()) {
                        if (slot == null || slot.isJsonNull()) {
                            continue;
                        }
                        String cell = slot.getAsString();
                        if (cell == null || cell.isEmpty()) {
                            continue;
                        }
                        int colon = cell.lastIndexOf(':');
                        if (colon <= 0) {
                            ingredients.add(new Ingredient(cell, 1));
                            continue;
                        }
                        int count = 1;
                        try {
                            count = Integer.parseInt(cell.substring(colon + 1));
                        } catch (NumberFormatException ignored) {
                            // A malformed count is treated as one rather than dropping the slot.
                        }
                        ingredients.add(new Ingredient(cell.substring(0, colon), Math.max(1, count)));
                    }
                    if (!ingredients.isEmpty()) {
                        parsed.put(entry.getKey(), List.copyOf(ingredients));
                    }
                }
            } catch (Exception e) {
                throw new IllegalStateException("Could not read recipes.json", e);
            }
            size = parsed.size();
            recipes = parsed;
        }
    }
}
